import type { UserStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

interface UserStatusEntry {
  name: string;
  variant: BadgeVariants;
}

export const userStatuses: Record<UserStatus, UserStatusEntry> = {
  new: { name: 'New', variant: 'default' },
  active: { name: 'Active', variant: 'success' },
  deleted: { name: 'Deleted', variant: 'default' },
  blocked: { name: 'Blocked', variant: 'destructive' },
};

export function getUserStatus(status: UserStatus): UserStatusEntry {
  return userStatuses[status] ?? { name: snakeCaseToCapitalizedCase(status), variant: 'default' };
}

export const userStatusesItems: SelectItem<UserStatus>[] = Object.entries(userStatuses).map(([value, { name }]) => ({
  value: value as UserStatus,
  name,
}));
